-- Fix two incorrect round_of_16 pairings generated by the previous winner mapping.
-- This SQL only updates public.matches.home_team / away_team for two scheduled matches.
-- It does not update predictions, players, coins, payout, points, or card data.

begin;

-- Dry-run preview before applying.
select
  id,
  start_time,
  home_team as old_home_team,
  away_team as old_away_team,
  case
    when id = 'c0b1adc5-7250-4ac8-a043-616595aab816' then 'Portugal'
    when id = 'cc97dc59-1746-491b-a587-f28ead263aa1' then 'USA'
    else home_team
  end as new_home_team,
  case
    when id = 'c0b1adc5-7250-4ac8-a043-616595aab816' then 'Spain'
    when id = 'cc97dc59-1746-491b-a587-f28ead263aa1' then 'Belgium'
    else away_team
  end as new_away_team
from public.matches
where id in (
  'c0b1adc5-7250-4ac8-a043-616595aab816',
  'cc97dc59-1746-491b-a587-f28ead263aa1'
)
order by start_time;

update public.matches
set
  home_team = 'Portugal',
  away_team = 'Spain'
where id = 'c0b1adc5-7250-4ac8-a043-616595aab816'
  and stage = 'round_of_16'
  and status in ('scheduled', 'not_started', 'open')
  and home_team = 'USA'
  and away_team = 'Spain';

update public.matches
set
  home_team = 'USA',
  away_team = 'Belgium'
where id = 'cc97dc59-1746-491b-a587-f28ead263aa1'
  and stage = 'round_of_16'
  and status in ('scheduled', 'not_started', 'open')
  and home_team = 'Belgium'
  and away_team = 'Portugal';

-- Verification.
select
  id,
  start_time,
  home_team,
  away_team,
  status
from public.matches
where id in (
  'c0b1adc5-7250-4ac8-a043-616595aab816',
  'cc97dc59-1746-491b-a587-f28ead263aa1'
)
order by start_time;

commit;
